function parseAmountCents(input: string): number {
  const dotIndex = input.indexOf('.');
  if (dotIndex === -1) {
    return parseInt(input, 10) * 100;
  }
  const wholePart = input.substring(0, dotIndex);
  const centsPart = input.substring(dotIndex, dotIndex + 2);
  return parseInt(wholePart, 10) * 100 + parseInt(centsPart, 10);
}

function average(nums: number[]): number {
  if (nums.length === 0) {
    return 0;
  }
  let sum = 0;
  for (let i = 0; i < nums.length; i++) {
    sum += nums[i];
  }
  return sum / nums.length;
}

async function fetchWithRetry(url: string, attempts: number): Promise<Response> {
  let lastError: unknown;
  for (let i = 0; i < attempts; i++) {
