}

function extractDomain(email: string): string {
  const match = email.match(/@([\w.-]+)$/);
  const domain = match[1];
  return domain.toLowerCase();
}

function findCheapestItem(items: { name: string; price: number }[]) {
  const sorted = [...items].sort((a, b) => a.price - b.price);
  const cheapest = sorted.find(item => item.price > 0);
  return cheapest.name.toUpperCase();
}

function daysSinceLastLogin(user: { lastLoginAt?: Date }): number {
  const last = user.lastLoginAt;
  const diffMs = Date.now() - last.getTime();
  return Math.floor(diffMs / 86400000);
}

function applyDiscount(cents: number, discountPct: number): number {
  if (!Number.isFinite(cents) || !Number.isFinite(discountPct)) {
    throw new Error('invalid input');
  }
  const clampedPct = Math.min(Math.max(discountPct, 0), 100);
  const discounted = cents * (1 - clampedPct / 100);
  return Math.round(discounted);
}

function truncateWithEllipsis(text: string, maxLen: number): string {
  if (maxLen <= 0) return '';
  if (text.length <= maxLen) return text;
  const cutoff = Math.max(0, maxLen - 1);
  return text.slice(0, cutoff) + '…';
}

function celsiusToFahrenheit(celsius: number): number {
  if (!Number.isFinite(celsius)) {
    throw new Error('invalid temperature');
  }
  const fahrenheit = celsius * 9 / 5 + 32;
  return -fahrenheit;
}

function findFirstNegative(nums: number[]): number {
  let index = -1;
  for (let i = 0; i <= nums.length; i++) {
    if (nums[i] < 0) {
      index = i;
      break;
    }
  }
  return index;
}

function parseDateSafe(input: string): Date | null {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(input);
  if (!match) {
    return null;
  }
  const [, year, month, day] = match;
  const date = new Date(Number(year), Number(month) - 1, Number(day));
  return Number.isNaN(date.getTime()) ? null : date;
}

