function parseQueryParams(query) {
  const result = {};
  const pairs = query.replace(/^\?/, '').split('&');
  for (const pair of pairs) {
    const [key, value] = pair.split('=');
    if (!key) continue;
    result[decodeURIComponent(key)] = decodeURIComponent(value || '');
  }
}

